import{_ as r,o as a,c as d,j as e,a as t}from"./chunks/framework.QCr1ZR1X.js";const p=JSON.parse('{"title":"思维导图-第5章-工业互联网平台","description":"","frontmatter":{},"headers":[],"relativePath":"mindmap/思维导图-第5章-工业互联网平台.md","filePath":"mindmap/思维导图-第5章-工业互联网平台.md","lastUpdated":1786967935000}'),c={name:"mindmap/思维导图-第5章-工业互联网平台.md"};function s(n,o,i,_,l,m){return a(),d("div",null,[...o[0]||(o[0]=[e("h1",{id:"思维导图-第5章-工业互联网平台",tabindex:"-1"},[t("思维导图-第5章-工业互联网平台 "),e("a",{class:"header-anchor",href:"#思维导图-第5章-工业互联网平台","aria-label":'Permalink to "思维导图-第5章-工业互联网平台"'},"​")],-1),e("div",{class:"mermaid"},'# 第5章 工业互联网平台 — 思维导图 ## 5.1 手机应用商店和工业平台的共同逻辑 - 类比：手机应用商店 → 工业互联网平台 - 平台降低工业APP开发门槛 - 标识解析：工业互联网的"身份证体系" - 给设备/零部件/产品分配唯一数字标识 - 了解即可 ## 5.2 工业互联网平台做什么：三层能力 - 向下：设备连接与管理 - SDK接入 - Modbus/MQTT/OPC UA协议适配 - 数字模型（设备画像） - 中间：数据存储与分析 - 时序数据库 - 流计算引擎（实时处理） - 批处理分析（历史回溯） - AI模型训练 - 向上：应用开发与托管 - 低代码开发工具 - API网关 - 微服务框架 ### 边缘与平台的分工 - 边缘管"现在"：实时判断、本地闭环控制 - 平台管"趋势"：历史分析、趋势预测、跨设备对比、AI模型训练 ### 案例：树根互联与三一重工 - 平台接入超120万台设备 - "挖掘机指数"：被经济学家用于预测宏观经济走势 - 从卖产品到卖服务 ## 5.3 中国工业互联网平台的版图 ### 两类基因 - "互联网向下做" - 阿里云IoT：云计算+AI向工业输出 - 华为FusionPlant：从芯片到5G到云的全栈 - "制造业向上做" - 树根互联：三一重工孵化，工程机械深刻理解 - 海尔卡奥斯：大规模定制模式 ### 双跨平台 - 工信部"跨行业跨领域工业互联网平台"评估 - 截至2025年约50家入选 - 代表国内最高水平 ## 5.4 Docker容器：让工业应用像手机APP一样部署 ### 集装箱的启示 - 应用+依赖打包成标准镜像 - 随处运行，环境一致 ### 比虚拟机更轻的隔离 - 容器共享宿主机内核 - 启动秒级，资源占用小 - 虚拟机模拟完整硬件，独立操作系统 - 启动分钟级，完全隔离 ### 三个核心概念 - 镜像（Image）：只读模板 - 容器（Container）：运行实例 - 仓库（Registry）：存放镜像 ### Docker常用命令速查 - docker pull：拉取镜像 - docker run：运行容器 - docker ps：查看运行中容器 - docker stop/rm：停止/删除容器 - docker rmi：删除镜像 - docker logs：查看日志 - docker exec：进入容器 ### Docker在工业场景中的价值 - 确保边缘和云端运行完全一致的软件环境 - 支持"云端管控、边缘执行"模式 ## 5.5 动手实践：Docker容器技术入门 ### 实践任务 - 安装Docker并验证 - 运行hello-world容器 - 运行Nginx容器 - 端口映射8080:80 - 浏览器访问验证 ## 5.6 动手实践：在Docker中部署Node-RED ### 实践任务 - 用Docker运行Node-RED - 端口映射1881:1880 - 双开对比 - 原生安装Node-RED（端口1880） - Docker容器Node-RED（端口1881） - 容器启停和删除操作练习 ### 课后拓展 - docker exec：进入容器内部 - Docker Compose：多容器编排 - -v卷映射：数据持久化 ## 🎯 课程思政 - 平台之上，规则先行——工业互联网平台的治理与合规 - 工信部对双跨平台有严格评估标准 - 平台运营须遵守《工业互联网安全管理办法》《关键信息基础设施安全保护条例》 - 数据安全保护是平台方的基本义务',-1)])])}const D=r(c,[["render",s]]);export{p as __pageData,D as default};
